QJ_ISI(30,[[78,1,5673,582,"عَمَّ يَتَسَآءَلُونَ","Tentang apakah mereka bertanya-tanya?"],[78,2,5674,582,"عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ","Tentang berita yang besar, (berita kebangkitan manusia hidup semula menerima balasannya)."],[78,3,5675,582,"ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ","Yang mereka (ragu-ragu dan) berselisihan mengenainya."],[78,4,5676,582,"كَلَّا سَيَعْلَمُونَ","Jangan! (Janganlah mereka bersikap demikian!) Mereka akan mengetahui (dengan yakin tentang kebenaran hari balasan itu)."],[78,5,5677,582,"ثُمَّ كَلَّا سَيَعْلَمُونَ","Sekali lagi jangan! (Janganlah mereka berselisihan!) Mereka akan mengetahui kelak (tentang apa yang akan menimpa mereka)."],[78,6,5678,582,"أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَٰدًۭا","(Mengapa kamu ragu-ragukan kekuasaan Kami menghidupkan semula orang-orang yang telah mati?) Bukankah Kami telah menjadikan bumi (terbentang luas) sebagai hamparan?"],[78,7,5679,582,"وَٱلْجِبَالَ أَوْتَادًۭا","Dan gunung-ganang sebagai pancang pasaknya?"],[78,8,5680,582,"وَخَلَقْنَٰكُمْ أَزْوَٰجًۭا","Dan Kami telah menciptakan kamu berpasang-pasang?"],[78,9,5681,582,"وَجَعَلْنَا نَوْمَكُمْ سُبَاتًۭا","Dan Kami telah menjadikan tidur kamu untuk berehat?"],[78,10,5682,582,"وَجَعَلْنَا ٱلَّيْلَ لِبَاسًۭا","Dan Kami telah menjadikan malam (dengan gelapnya) sebagai pakaian (yang melindungi)?"],[78,11,5683,582,"وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًۭا","Dan Kami telah menjadikan siang (dengan cahaya terangnya) - masa untuk mencari rezeki?"],[78,12,5684,582,"وَبَنَيْنَا فَوْقَكُمْ سَبْعًۭا شِدَادًۭا","Dan Kami telah membina di atas kamu tujuh petala (langit) yang kuat kukuh?"],[78,13,5685,582,"وَجَعَلْنَا سِرَاجًۭا وَهَّاجًۭا","Dan Kami telah mengadakan matahari menjadi lampu yang terang-benderang cahayanya?"],[78,14,5686,582,"وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءًۭ ثَجَّاجًۭا","Dan Kami telah menurunkan dari awan, air (hujan) yang mencurah-curah, -"],[78,15,5687,582,"لِّنُخْرِجَ بِهِۦ حَبًّۭا وَنَبَاتًۭا","Untuk Kami mengeluarkan dengan air itu, biji-bijian dan tumbuh-tumbuhan, -"],[78,16,5688,582,"وَجَنَّٰتٍ أَلْفَافًا","Serta kebun-kebun yang subur bertaut-taut pokoknya?"],[78,17,5689,582,"إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَٰتًۭا","Sesungguhnya hari pemutusan hukum itu, adalah satu masa yang ditentukan,"],[78,18,5690,582,"يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًۭا","Iaitu masa ditiup sangkakala, lalu kamu (bangkit hidup) serta datang berpuak-puak (ke Padang Mahsyar);"],[78,19,5691,582,"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا","Dan (pada masa itu) langit dipecah belahkan sehingga tiap-tiap belahannya menjadi ibarat pintu yang terbuka luas,"],[78,20,5692,582,"وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا","Dan gunung-ganang - setelah dihancurkan - diterbangkan ke angkasa, lalu menjadilah ia bayangan semata-mata seperti riak sinaran panas di padang pasir."],[78,21,5693,582,"إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًۭا","Sesungguhnya neraka Jahannam adalah disediakan -"],[78,22,5694,582,"لِّلطَّٰغِينَ مَـَٔابًۭا","Untuk orang-orang yang melampaui batas hukum Tuhan, sebagai tempat kembalinya."],[78,23,5695,582,"لَّٰبِثِينَ فِيهَآ أَحْقَابًۭا","Mereka tinggal di dalamnya berkurun-kurun lamanya."],[78,24,5696,582,"لَّا يَذُوقُونَ فِيهَا بَرْدًۭا وَلَا شَرَابًا","Mereka tidak dapat merasai udara yang sejuk di dalamnya, dan tidak pula sebarang minuman -"],[78,25,5697,582,"إِلَّا حَمِيمًۭا وَغَسَّاقًۭا","Kecuali air panas yang menggelegak, dan air danur yang mengalir, -"],[78,26,5698,582,"جَزَآءًۭ وِفَاقًا","Sebagai balasan yang sesuai (dengan amal mereka yang buruk)."],[78,27,5699,582,"إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًۭا","Kerana sesungguhnya mereka dahulu tidak menaruh ingatan terhadap hari hitungan amal,"],[78,28,5700,582,"وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًۭا","Dan mereka telah mendustakan dengan sesungguh-sungguhnya akan ayat-ayat keterangan Kami;"],[78,29,5701,582,"وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًۭا","Dan tiap-tiap sesuatu dari bawaan hidupnya, telah Kami hitung secara bertulis."],[78,30,5702,582,"فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا","(Setelah mereka masuk ke dalam neraka, dikatakan kepada mereka: \"Oleh sebab kamu telah mendustakan ayat-ayat Kami) maka rasalah kamu (azab yang disediakan), kerana Kami tidak akan melakukan selain dari menambah berbagai azab kepada kamu\"."],[78,31,5703,583,"إِنَّ لِلْمُتَّقِينَ مَفَازًا","Sesungguhnya orang-orang yang bertaqwa, disediakan Syurga tempat mereka beroleh apa yang mereka ingini."],[78,32,5704,583,"حَدَآئِقَ وَأَعْنَٰبًۭا","(Mereka akan beroleh) taman-taman bunga dan kebun-kebun buah-buahan, terutama anggur;"],[78,33,5705,583,"وَكَوَاعِبَ أَتْرَابًۭا","Dan perawan-perawan yang sebaya umurnya;"],[78,34,5706,583,"وَكَأْسًۭا دِهَاقًۭا","Serta piala atau gelas yang penuh dengan minuman;"],[78,35,5707,583,"لَّا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا كِذَّٰبًۭا","Mereka tidak mendengar di dalam Syurga itu perkataan yang sia-sia, dan tiada pula perkataan yang dusta;"],[78,36,5708,583,"جَزَآءًۭ مِّن رَّبِّكَ عَطَآءً حِسَابًۭا","Sebagai balasan dari Tuhanmu, iaitu satu limpah kurnia yang dikira cukup (menurut yang dijanjikanNya),"],[78,37,5709,583,"رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا","Tuhan yang mentadbirkan tujuh petala langit dan bumi serta apa yang ada di antara keduanya, Tuhan Yang Maha Pemurah, tidak ada sesiapapun diberi kuasa berkata-kata denganNya (untuk memohon pertimbangan tentang balasan atau pengurniaan itu);"],[78,38,5710,583,"يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّۭا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًۭا","(Tambahan pula) pada masa Jibril dan malaikat-malaikat yang lain berdiri bersaf-saf (menunggu perintah Tuhan), tidak ada yang berani berkata-kata (memohon pertimbangan) melainkan yang telah diizinkan baginya oleh Tuhan Yang Maha Pemurah, serta ia berkata benar."],[78,39,5711,583,"ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","Itulah keterangan-keterangan mengenai hari (kiamat) yang sungguh tetap berlakunya; maka sesiapa yang mahukan kebaikan dirinya, dapatlah ia mengambil jalan dan cara kembali kepada Tuhannya (dengan iman dan amal yang soleh)!"],[78,40,5712,583,"إِنَّآ أَنذَرْنَٰكُمْ عَذَابًۭا قَرِيبًۭا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا","Sesungguhnya (dengan keterangan-keterangan yang tersebut), Kami memberi amaran kepada kamu mengenai azab yang dekat (masa datangnya), - iaitu hari seseorang melihat apa yang telah diusahakannya; dan orang yang kafir akan berkata (pada hari itu): \"Alangkah baiknya kalau aku menjadi tanah (supaya aku tidak dibangkitkan untuk dihitung amalku dan menerima balasan)\"."],[79,1,5713,583,"وَٱلنَّٰزِعَٰتِ غَرْقًۭا","Demi (makhluk-makhluk) yang mencabut (apa yang ditugaskan mencabutnya) dengan cara yang sekasar-kasarnya;"],[79,2,5714,583,"وَٱلنَّٰشِطَٰتِ نَشْطًۭا","Dan yang menarik (apa yang ditugaskan menariknya) dengan cara yang selembut-lembutnya;"],[79,3,5715,583,"وَٱلسَّٰبِحَٰتِ سَبْحًۭا","Dan demi (makhluk-makhluk) yang cergas bergerak (menerima perintah) dengan gerak yang secergas-cergasnya;"],[79,4,5716,583,"فَٱلسَّٰبِقَٰتِ سَبْقًۭا","Lalu masing-masing berlumba-lumba dahulu-mendahului (menjalankan tugasnya) dengan cara yang sesungguh-sungguhnya;"],[79,5,5717,583,"فَٱلْمُدَبِّرَٰتِ أَمْرًۭا","Serta menyempurnakan tadbir urusan alam yang diperintahkan kepadanya; (sumpah demi sumpah, sesungguhnya kamu akan dibangkitkan hidup semula pada hari kiamat)! -"],[79,6,5718,583,"يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ","Pada masa berlakunya \"tiupan sangkakala yang pertama\" yang menggoncangkan alam, (sehingga mati segala yang bernyawa dan punah-ranah sekalian makhluk selain dari yang dikecualikan),"],[79,7,5719,583,"تَتْبَعُهَا ٱلرَّادِفَةُ","Tiupan yang pertama itu diikuti oleh tiupan yang kedua, (yang menyebabkan orang-orang yang mati semuanya hidup semula serta keluar dari kubur masing-masing);"],[79,8,5720,583,"قُلُوبٌۭ يَوْمَئِذٍۢ وَاجِفَةٌ","Hati (manusia) pada hari itu berdebar-debar takut,"],[79,9,5721,583,"أَبْصَٰرُهَا خَٰشِعَةٌۭ","Pemandangannya tunduk gerun."],[79,10,5722,583,"يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ","Mereka (yang ingkar) berkata: \"Sungguhkah kita akan dikembalikan hidup seperti keadaan di dunia dahulu?"],[79,11,5723,583,"أَءِذَا كُنَّا عِظَٰمًۭا نَّخِرَةًۭ","\"Bolehkah (dihidupkan semula) sesudah kita menjadi tulang yang reput?\""],[79,12,5724,583,"قَالُوا۟ تِلْكَ إِذًۭا كَرَّةٌ خَاسِرَةٌۭ","Mereka berkata lagi (secara mengejek: \"Kalaulah berlaku) yang demikian, sudah tentu kembalinya kita (hidup semula) itu satu perkara yang merugikan!\""],[79,13,5725,583,"فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ","(Menghidupkan semula tidaklah sukar), kerana berlakunya perkara itu hanyalah dengan satu jeritan (yang terbit dari tiupan sangkakala yang kedua), -"],[79,14,5726,583,"فَإِذَا هُم بِٱلسَّاهِرَةِ","Yang menyebabkan mereka dengan serta-merta berada di muka bumi yang putih rata."],[79,15,5727,583,"هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","Sudahkah sampai kepadamu (wahai Muhammad) perihal Nabi Musa?"],[79,16,5728,584,"إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى","Ketika ia diseru oleh Tuhannya di \"Wadi Tuwa\" yang suci; -"],[79,17,5729,584,"ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ","(Lalu diperintahkan kepadanya): \"Pergilah kepada Firaun, sesungguhnya ia telah melampaui batas (dalam kekufuran dan kezalimannya);"],[79,18,5730,584,"فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","\"Serta katakanlah kepadanya: `Adakah engkau suka hendak mensucikan dirimu (dari kekufuran)?"],[79,19,5731,584,"وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ","`Dan mahukah, aku tunjuk kepadamu jalan mengenal Tuhanmu, supaya engkau merasa takut (melanggar perintahNya)? ' \""],[79,20,5732,584,"فَأَرَىٰهُ ٱلْءَايَةَ ٱلْكُبْرَىٰ","(Setelah Nabi Musa menyempurnakan perintah Tuhannya, dan Firaun pun meminta bukti kebenarannya); maka Nabi Musa memperlihatkan kepada Firaun: mukjizat yang besar."],[79,21,5733,584,"فَكَذَّبَ وَعَصَىٰ","Lalu Firaun mendustakan (Nabi Musa) dan menderhaka (kepada Allah);"],[79,22,5734,584,"ثُمَّ أَدْبَرَ يَسْعَىٰ","Kemudian ia berpaling ingkar sambil menjalankan usahanya (menentang Nabi Musa)."],[79,23,5735,584,"فَحَشَرَ فَنَادَىٰ","Lalu ia menghimpunkan orang-orangnya dan menyeru, -"],[79,24,5736,584,"فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ","Dengan berkata: \"Akulah tuhan kamu, yang tertinggi\"."],[79,25,5737,584,"فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْءَاخِرَةِ وَٱلْأُولَىٰٓ","Maka Allah menyeksa Firaun di akhirat dan di dunia ini, dengan azab yang menakutkan sesiapa yang mengetahuinya."],[79,26,5738,584,"إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّمَن يَخْشَىٰٓ","Sesungguhnya yang demikian itu mengandungi pelajaran yang mendatangkan iktibar bagi orang-orang yang takut (melanggar perintah Tuhannya)."],[79,27,5739,584,"ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا","(Wahai golongan yang ingkarkan kebangkitan hidup semula!) Kamukah yang sukar diciptakan atau langit? Tuhan telah membinanya (dengan Kukuh)!"],[79,28,5740,584,"رَفَعَ سَمْكَهَا فَسَوَّىٰهَا","Ia telah meninggikan bangunan langit itu lalu menyempurnaKannya,"],[79,29,5741,584,"وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا","Dan Ia menjadikan malamnya gelap-gelita, serta menjadikan siangnya terang-benderang."],[79,30,5742,584,"وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ","Dan bumi sesudah itu dihamparkannya (untuk kemudahan penduduknya), -"],[79,31,5743,584,"أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا","Ia mengeluarkan dari bumi itu: airnya dan tumbuh-tumbuhannya;"],[79,32,5744,584,"وَٱلْجِبَالَ أَرْسَىٰهَا","Dan gunung-ganang pula dikukuhkan letaknya (di bumi, sebagai pancang pasak yang menetapnya);"],[79,33,5745,584,"مَتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ","(Semuanya itu) untuk kegunaan kamu dan binatang-binatang ternak kamu."],[79,34,5746,584,"فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ","Maka apabila datang hari yang bencananya amat besar, -"],[79,35,5747,584,"يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ","Iaitu hari manusia akan mengingati apa yang telah diusahakannya, -"],[79,36,5748,584,"وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ","Dan neraka diperlihatkan kepada sesiapa sahaja yang dapat melihatnya, -"],[79,37,5749,584,"فَأَمَّا مَن طَغَىٰ","Maka (dapatlah masing-masing mengetahui kesudahannya); adapun orang yang melampau (perbuatan derhakanya), -"],[79,38,5750,584,"وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","Serta ia mengutamakan kehidupan dunia semata-mata, -"],[79,39,5751,584,"فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ","Maka sesungguhnya neraka Jahanamlah tempat kediamannya."],[79,40,5752,584,"وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ","Adapun orang yang takutkan keadaan semasa ia berdiri di mahkamah Tuhannya, (untuk dihitung amalnya), serta ia menahan dirinya dari menurut hawa nafsu, -"],[79,41,5753,584,"فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ","Maka sesungguhnya Syurgalah tempat kediamannya."],[79,42,5754,584,"يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا","Mereka (yang ingkar) selalu bertanya kepadamu (wahai Muhammad) tentang hari kiamat: \"Bilakah masa datangnya?\""],[79,43,5755,584,"فِيمَ أَنتَ مِن ذِكْرَىٰهَآ","Apa hubungannya tugasmu dengan (soal) menerangkan masa kedatangan hari kiamat itu?"],[79,44,5756,584,"إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","Kepada Tuhanmu lah terserah kesudahan ilmu mengenainya."],[79,45,5757,584,"إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا","Tugasmu hanyalah memberi amaran kepada orang yang takut akan huru-hara hari kiamat itu."],[79,46,5758,584,"كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا","(Sangatlah dahsyatnya huru-hara hari itu, sehingga orang-orang yang bersalah merasa) pada masa melihatnya: seolah-olah mereka tidak tinggal di dunia melainkan sekadar satu petang atau paginya sahaja."],[80,1,5759,585,"عَبَسَ وَتَوَلَّىٰٓ","Ia memasamkan muka dan berpaling,"],[80,2,5760,585,"أَن جَآءَهُ ٱلْأَعْمَىٰ","Kerana ia didatangi orang buta."],[80,3,5761,585,"وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","Dan apa jalannya engkau dapat mengetahui (tujuannya, wahai Muhammad) ? Barangkali ia mahu membersihkan hatinya (dengan pelajaran ugama yang didapatinya daripadamu)! -"],[80,4,5762,585,"أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ","Ataupun ia mahu mendapat peringatan, supaya peringatan itu memberi manfaat kepadanya."],[80,5,5763,585,"أَمَّا مَنِ ٱسْتَغْنَىٰ","Adapun orang yang merasa keadaannya telah cukup, tidak berhajat lagi (kepada ajaran Al-Quran),"],[80,6,5764,585,"فَأَنتَ لَهُۥ تَصَدَّىٰ","Maka engkau bersungguh-sungguh melayaninya."],[80,7,5765,585,"وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ","Padahal engkau tidak bersalah kalau ia tidak mahu membersihkan dirinya (dari keingkarannya)."],[80,8,5766,585,"وَأَمَّا مَن جَآءَكَ يَسْعَىٰ","Adapun orang yang segera datang kepadamu,"],[80,9,5767,585,"وَهُوَ يَخْشَىٰ","Dengan perasaan takutnya (melanggar perintah-perintah Allah), -"],[80,10,5768,585,"فَأَنتَ عَنْهُ تَلَهَّىٰ","Maka engkau berlengah-lengah melayaninya."],[80,11,5769,585,"كَلَّآ إِنَّهَا تَذْكِرَةٌۭ","Janganlah melakukan lagi yang sedemikian itu! Sebenarnya ayat-ayat Al-Quran adalah pengajaran dan peringatan (yang mencukupi)."],[80,12,5770,585,"فَمَن شَآءَ ذَكَرَهُۥ","Maka sesiapa yang mahukan kebaikan dirinya, dapatlah ia mengambil peringatan daripadanya."],[80,13,5771,585,"فِى صُحُفٍۢ مُّكَرَّمَةٍۢ","(Ayat-ayat Suci itu tersimpan) dalam naskhah-naskhah yang dimuliakan, -"],[80,14,5772,585,"مَّرْفُوعَةٍۢ مُّطَهَّرَةٍۭ","Yang tinggi darjatnya, lagi suci (dari segala gangguan), -"],[80,15,5773,585,"بِأَيْدِى سَفَرَةٍۢ","(Terpelihara) di tangan malaikat-malaikat yang menyalinnya dari Lauh Mahfuz;"],[80,16,5774,585,"كِرَامٍۭ بَرَرَةٍۢ","(Malaikat-malaikat) yang mulia, lagi yang berbakti."],[80,17,5775,585,"قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ","Binasalah hendaknya manusia (yang ingkar) itu, betapa besar kekufurannya?"],[80,18,5776,585,"مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ","(Tidakkah ia memikirkan) dari apakah ia diciptakan oleh Allah? -"],[80,19,5777,585,"مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","Dari air mani diciptakanNya, serta dilengkapkan keadaannya dengan persediaan untuk bertanggungjawab;"],[80,20,5778,585,"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","Kemudian jalan (baik dan jahat), dimudahkan Tuhan kepadanya (untuk menimbang dan mengambil mana satu yang ia pilih);"],[80,21,5779,585,"ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ","Kemudian dimatikannya, lalu diperintahkan supaya ia dikuburkan;"],[80,22,5780,585,"ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","Kemudian apabila Allah kehendaki dibangkitkannya (hidup semula)."],[80,23,5781,585,"كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ","Janganlah hendaknya ia kufur ingkar lagi! Sebenarnya ia belum menunaikan apa yang diperintahkan kepadanya."],[80,24,5782,585,"فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","(Kalaulah ia tidak memikirkan asal dan kesudahan dirinya), maka hendaklah manusia melihat kepada makanannya (bagaimana kami mentadbirkannya):"],[80,25,5783,585,"أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّۭا","Sesungguhnya kami telah mencurahkan hujan dengan curahan yang menakjubkan."],[80,26,5784,585,"ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّۭا","Kemudian kami belah-belahkan bumi dengan belahan yang sesuai dengan tumbuh-tumbuhan, -"],[80,27,5785,585,"فَأَنۢبَتْنَا فِيهَا حَبًّۭا","Lalu Kami tumbuhkan pada bumi biji-bijian,"],[80,28,5786,585,"وَعِنَبًۭا وَقَضْبًۭا","Dan buah anggur serta sayur-sayuran,"],[80,29,5787,585,"وَزَيْتُونًۭا وَنَخْلًۭا","Dan Zaitun serta pohon-pohon kurma,"],[80,30,5788,585,"وَحَدَآئِقَ غُلْبًۭا","Dan taman-taman yang menghijau subur,"],[80,31,5789,585,"وَفَٰكِهَةًۭ وَأَبًّۭا","Dan berbagai buah-buahan serta bermacam-macam rumput, -"],[80,32,5790,585,"مَّتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ","Untuk kegunaan kamu dan binatang-binatang ternak kamu."],[80,33,5791,585,"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","Kemudian (ingatlah keadaan yang berlaku) apabila datang suara jeritan yang dahsyat, -"],[80,34,5792,585,"يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ","Pada hari seseorang itu lari dari saudaranya,"],[80,35,5793,585,"وَأُمِّهِۦ وَأَبِيهِ","Dan ibunya serta bapanya,"],[80,36,5794,585,"وَصَٰحِبَتِهِۦ وَبَنِيهِ","Dan isterinya serta anak-anaknya; -"],[80,37,5795,585,"لِكُلِّ ٱمْرِئٍۢ مِّنْهُمْ يَوْمَئِذٍۢ شَأْنٌۭ يُغْنِيهِ","Kerana tiap-tiap seorang dari mereka pada hari itu, ada perkara-perkara yang cukup untuk menjadikannya sibuk dengan hal dirinya sahaja."],[80,38,5796,585,"وُجُوهٌۭ يَوْمَئِذٍۢ مُّسْفِرَةٌۭ","Muka (orang-orang yang beriman) pada hari itu berseri-seri,"],[80,39,5797,585,"ضَاحِكَةٌۭ مُّسْتَبْشِرَةٌۭ","Tertawa, lagi bersuka ria;"],[80,40,5798,585,"وَوُجُوهٌۭ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۭ","Dan muka (orang-orang yang ingkar) pada hari itu penuh berdebu,"],[80,41,5799,585,"تَرْهَقُهَا قَتَرَةٌ","Diliputi oleh warna hitam legam dan gelap-gelita. -"],[80,42,5800,585,"أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ","Mereka itu ialah orang-orang yang kafir, yang derhaka."],[81,1,5801,586,"إِذَا ٱلشَّمْسُ كُوِّرَتْ","Apabila matahari dilingkari cahayanya (dan hilang lenyap);"],[81,2,5802,586,"وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ","Dan apabila bintang-bintang gugur berselerak;"],[81,3,5803,586,"وَإِذَا ٱلْجِبَالُ سُيِّرَتْ","Dan apabila gunung-ganang di terbangkan ke angkasa (setelah dihancurkan menjadi debu);"],[81,4,5804,586,"وَإِذَا ٱلْعِشَارُ عُطِّلَتْ","Dan apabila unta-unta yang bunting terbiar;"],[81,5,5805,586,"وَإِذَا ٱلْوُحُوشُ حُشِرَتْ","Dan apabila binatang-binatang liar dihimpunkan;"],[81,6,5806,586,"وَإِذَا ٱلْبِحَارُ سُجِّرَتْ","Dan apabila lautan meluap-luap bercampur-baur;"],[81,7,5807,586,"وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ","Dan apabila tiap-tiap diri disatukan dengan pasangannya;"],[81,8,5808,586,"وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ","Dan apabila anak perempuan yang ditanam hidup-hidup: ditanya, -"],[81,9,5809,586,"بِأَىِّ ذَنۢبٍۢ قُتِلَتْ","Dengan dosa apakah ia dibunuh?"],[81,10,5810,586,"وَإِذَا ٱلصُّحُفُ نُشِرَتْ","Dan apabila surat-surat amal dibentangkan;"],[81,11,5811,586,"وَإِذَا ٱلسَّمَآءُ كُشِطَتْ","Dan apabila langit ditanggalkan dari tempatnya;"],[81,12,5812,586,"وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ","Dan apabila neraka dinyalakan menjulang;"],[81,13,5813,586,"وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ","Dan apabila Syurga didekatkan;"],[81,14,5814,586,"عَلِمَتْ نَفْسٌۭ مَّآ أَحْضَرَتْ","(Setelah semuanya itu berlaku), tiap-tiap orang akan mengetahui tentang amal yang telah dibawanya."],[81,15,5815,586,"فَلَآ أُقْسِمُ بِٱلْخُنَّسِ","Oleh itu, Aku bersumpah dengan bintang-bintang yang tenggelam timbul;"],[81,16,5816,586,"ٱلْجَوَارِ ٱلْكُنَّسِ","Yang beredar, juga yang tetap pada tempatnya;"],[81,17,5817,586,"وَٱلَّيْلِ إِذَا عَسْعَسَ","Dan malam, apabila ia hampir habis,"],[81,18,5818,586,"وَٱلصُّبْحِ إِذَا تَنَفَّسَ","Dan siang, apabila ia mulai terang;"],[81,19,5819,586,"إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ","Sebenarnya Al-Quran itu, sungguh-sungguh Kalamullah (yang disampaikan oleh Jibril) Utusan yang mulia,"],[81,20,5820,586,"ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍۢ","Yang kuat gagah, lagi berkedudukan tinggi di sisi Allah yang mempunyai Arasy,"],[81,21,5821,586,"مُّطَاعٍۢ ثَمَّ أَمِينٍۢ","Yang ditaati di sana (dalam kalangan malaikat), lagi dipercayai."],[81,22,5822,586,"وَمَا صَاحِبُكُم بِمَجْنُونٍۢ","Dan sebenarnya sahabat kamu (Nabi Muhammad) itu (wahai golongan yang menentang Islam), bukanlah ia seorang gila (seperti yang kamu tuduh);"],[81,23,5823,586,"وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ","Dan (Nabi Muhammad yakin bahawa yang disampaikan kepadanya ialah wahyu dari Tuhan, kerana) demi sesungguhnya! Nabi Muhammad telah mengenal dan melihat Jibril di kaki langit yang nyata."],[81,24,5824,586,"وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍۢ","Dan bukanlah Nabi Muhammad seorang yang boleh dituduh dan disangka buruk, terhadap penyampaiannya mengenai perkara-perkara yang ghaib."],[81,25,5825,586,"وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍۢ رَّجِيمٍۢ","Dan sebenarnya Al-Quran itu bukanlah perkataan Syaitan yang kena rejam."],[81,26,5826,586,"فَأَيْنَ تَذْهَبُونَ","(Dengan yang demikian) maka ke manakah kamu hendak pergi (kiranya kamu masih menyeleweng dari jalan Al-Quran)?"],[81,27,5827,586,"إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ","Al-Quran itu tidak lain hanyalah peringatan bagi seluruh penduduk alam:"],[81,28,5828,586,"لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ","Iaitu bagi sesiapa dari kamu yang mahu tetap teguh di atas jalan (Islam) yang betul."],[81,29,5829,586,"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ","Dan kamu tidak dapat menentukan kemahuan kamu (mengenai sesuatupun), kecuali dengan cara yang diatur oleh Allah, Tuhan yang memelihara dan mentadbirkan seluruh alam."],[82,1,5830,587,"إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ","Apabila langit terbelah;"],[82,2,5831,587,"وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ","Dan apabila bintang-bintang gugur bertaburan;"],[82,3,5832,587,"وَإِذَا ٱلْبِحَارُ فُجِّرَتْ","Dan apabila lautan pecah bercampur-baur;"],[82,4,5833,587,"وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ","Dan apabila kubur-kubur dibongkarkan, -"],[82,5,5834,587,"عَلِمَتْ نَفْسٌۭ مَّا قَدَّمَتْ وَأَخَّرَتْ","(Setelah semuanya itu berlaku), tiap-tiap orang akan mengetahui apa yang telah dikerjakan dan ditinggalkannya."],[82,6,5835,587,"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ","Wahai manusia! Apakah yang memperdayakanmu - (berlaku derhaka) kepada Tuhanmu yang Maha Pemurah? -"],[82,7,5836,587,"ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","Tuhan yang telah mencipta dan mengatur kejadianmu, lalu menjadikan anggotamu sesuai (dengan tujuan yang kerananya anggota itu diadakan), serta menjadikan (binaan tubuh badanmu) sama padan dengan kekuatannya;"],[82,8,5837,587,"فِىٓ أَىِّ صُورَةٍۢ مَّا شَآءَ رَكَّبَكَ","Dalam bentuk dan rupa apa sahaja yang dikehendakiNya, Ia menyusun kejadianmu."],[82,9,5838,587,"كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ","Sebenarnya tidak ada yang memperdayakan kamu (hai golongan yang ingkar)! Bahkan kamu sendiri tidak percayakan adanya hari pembalasan."],[82,10,5839,587,"وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ","Padahal sesungguhnya, ada malaikat-malaikat yang menjaga dan mengawas segala bawaan kamu,"],[82,11,5840,587,"كِرَامًۭا كَٰتِبِينَ","(Mereka adalah makhluk) yang mulia (di sisi Allah), lagi ditugaskan menulis (amal-amal kamu);"],[82,12,5841,587,"يَعْلَمُونَ مَا تَفْعَلُونَ","Mereka mengetahui apa yang kamu lakukan."],[82,13,5842,587,"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍۢ","(Gunanya catitan malaikat-malaikat itu ialah: untuk menyatakan siapa yang berbakti dan siapa yang bersalah) - kerana sesungguhnya: orang-orang yang berbakti (dengan taat dan amal kebajikan), tetap berada dalam Syurga yang penuh nikmat;"],[82,14,5843,587,"وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍۢ","Dan sesungguhnya orang-orang yang bersalah, bertempat dalam neraka yang menjulang-julang."],[82,15,5844,587,"يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ","Mereka menderita bakaran neraka itu pada hari pembalasan,"],[82,16,5845,587,"وَمَا هُمْ عَنْهَا بِغَآئِبِينَ","Dan mereka (sentiasa berada dalam azab seksanya), tidak ghaib daripadanya."],[82,17,5846,587,"وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","Dan apa jalannya engkau dapat mengetahui kedahsyatan hari pembalasan itu?"],[82,18,5847,587,"ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","Sekali lagi, apa jalannya engkau dapat mengetahui kedahsyatan hari pembalasan itu?"],[82,19,5848,587,"يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ","(Hari itu ialah) hari seseorang tidak dapat memberikan pertolongan sedikitpun kepada orang lain, dan segala urusan pada hari itu tertentu bagi Allah."],[83,1,5849,587,"وَيْلٌۭ لِّلْمُطَفِّفِينَ","Kecelakaan besar bagi orang-orang yang curang (dalam timbangan dan sukatan),"],[83,2,5850,587,"ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ","Iaitu mereka yang apabila menerima sukatan (gantang cupak) dari orang lain mereka mengambilnya dengan cukup,"],[83,3,5851,587,"وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ","Dan (sebaliknya) apabila mereka menyukat atau menimbang untuk orang lain, mereka kurangi."],[83,4,5852,587,"أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ","Tidakkah mereka menyangka bahawa mereka akan dibangkitkan (hidup semula sesudah mati)?"],[83,5,5853,587,"لِيَوْمٍ عَظِيمٍۢ","Pada hari (kiamat) yang amat besar (huru-haranya),"],[83,6,5854,587,"يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ","Hari berdiri manusia untuk mengadap Tuhan sekalian alam?"],[83,7,5855,588,"كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ","Tidak sepatutnya (mereka melakukan perbuatan yang salah itu dan melalaikan hari akhirat)! Sesungguhnya \"kitab suratan amal\" orang-orang yang berdosa itu (didaftarkan) dalam \"Sijjiin\"."],[83,8,5856,588,"وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ","Dan apa jalannya engkau dapat mengetahui: apa dia \"Sijjiin\" itu,"],[83,9,5857,588,"كِتَٰبٌۭ مَّرْقُومٌۭ","Ialah (tempat simpanan) kitab catitan yang jelas nyata, (yang menghimpunkan amalan orang-orang yang berdosa)."],[83,10,5858,588,"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ","Kecelakaan besar, pada hari itu, bagi orang-orang yang mendustakan -"],[83,11,5859,588,"ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ","Iaitu mereka yang mendustakan hari pembalasan."],[83,12,5860,588,"وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ","Dan tiada yang mendustakannya melainkan tiap-tiap orang yang melampaui batas (kebenaran), lagi amat derhaka!"],[83,13,5861,588,"إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ","(Sehingga) apabila ia dibacakan kepadanya ayat-ayat Kami, ia berkata:\" Ini ialah dongeng orang-orang dahulu kala!\""],[83,14,5862,588,"كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ","Sebenarnya! (Ayat-ayat Kami itu tidak ada cacatnya) bahkan mata hati mereka telah diselaputi kekotoran (dosa), dengan sebab (perbuatan kufur dan maksiat) yang mereka kerjakan."],[83,15,5863,588,"كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ","Jangan lagi mereka berlaku demikian! (kalau tidak), mereka pada hari itu, tetap terdinding dari (rahmat) Tuhannya."],[83,16,5864,588,"ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ","Kemudian, sesungguhnya mereka akan menderita bakaran neraka."],[83,17,5865,588,"ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ","Akhirnya dikatakan (kepada mereka): \"Inilah dia (azab seksa) yang kamu dustakan dahulu.\""],[83,18,5866,588,"كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ","Ingatlah wahai manusia! Sesungguhnya \"kitab suratan amal\" orang-orang yang berbakti (dengan taat dan amal kebajikan), adalah (didaftarkan) dalam\" Illiyiin\"."],[83,19,5867,588,"وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ","Dan apa jalannya engkau dapat mengetahui, apa dia \"Illiyiin\" itu?"],[83,20,5868,588,"كِتَٰبٌۭ مَّرْقُومٌۭ","Ialah (tempat simpanan) kitab catitan yang jelas nyata,"],[83,21,5869,588,"يَشْهَدُهُ ٱلْمُقَرَّبُونَ","Yang disaksikan oleh sekumpulan malaikat, yang didampingkan Tuhan di sisinya."],[83,22,5870,588,"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ","Sesungguhnya orang-orang yang berbakti (dengan taat dan amal kebajikan), tetap berada di dalam Syurga yang penuh nikmat:"],[83,23,5871,588,"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","Mereka berehat di atas pelamin-pelamin (yang berhias), sambil melihat (segala keindahan dan kemuliaan yang disediakan untuk mereka di situ)."],[83,24,5872,588,"تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ","Engkau dapat melihat pada muka mereka: cahaya nikmat yang mereka perolehi."],[83,25,5873,588,"يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ","Mereka diberi minum dari satu minuman yang termeterai bekasnya,"],[83,26,5874,588,"خِتَٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ","Meterainya kasturi; - dan untuk (memperolehi nikmat kesenangan) itu hendaknya berlumba-lumba mereka yang ingin merebut kelebihan dan kesenangan;"],[83,27,5875,588,"وَمِزَاجُهُۥ مِن تَسْنِيمٍ","Dan campuran minuman itu adalah dari \"Tasnim\":"],[83,28,5876,588,"عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ","laitu matair yang diminum daripadanya oleh orang-orang yang di dampingkan (Tuhan di sisiNya)."],[83,29,5877,588,"إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ","Sesungguhnya orang-orang yang derhaka, mereka selalu tertawakan orang-orang yang beriman."],[83,30,5878,588,"وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ","Dan apabila orang-orang yang beriman lalu dekat mereka, mereka mengerling dan memejam celikkan mata sesama sendiri (mencemuhnya)."],[83,31,5879,588,"وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ","Dan apabila mereka kembali kepada kaum keluarganya, mereka kembali dengan riang gembira;"],[83,32,5880,588,"وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ","Dan apabila mereka melihat orang-orang yang beriman, mereka berkata: \"Sesungguhnya orang-orang itu adalah golongan yang sesat!\""],[83,33,5881,588,"وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ","Pada hal mereka tidak diutus untuk menjaga sesat atau tidaknya orang-orang yang beriman itu!"],[83,34,5882,588,"فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ","Maka pada hari ini, orang-orang yang beriman pula tertawakan orang yang kafir itu."],[83,35,5883,589,"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","Sambil mereka berehat di atas pelamin-pelamin (yang berhias), serta melihat (hal yang berlaku kepada musuhnya)."],[83,36,5884,589,"هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ","(Untuk menambahkan kegembiraan mereka, mereka ditanya): \"Bukankah orang-orang yang kafir itu telah dibalas akan apa yang mereka telah kerjakan dahulu?\""],[84,1,5885,589,"إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ","Apabila langit terbelah,"],[84,2,5886,589,"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","Serta mematuhi perintah Tuhannya, dan sudah semestinya ia patuh;"],[84,3,5887,589,"وَإِذَا ٱلْأَرْضُ مُدَّتْ","Dan apabila bumi diratakan,"],[84,4,5888,589,"وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ","Serta mengeluarkan apa yang di dalamnya, dan menjadi kosong,"],[84,5,5889,589,"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","Serta mematuhi perintah Tuhannya, dan sudah semestinya ia patuh; - (Maka pada saat itu tiap-tiap seorang akan mengetahui apa yang telah dilakukannya)."],[84,6,5890,589,"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَٰقِيهِ","Wahai manusia! Sesungguhnya engkau sentiasa berpenat-lelah (menjalankan keadaan hidupmu) dengan sedaya upayamu hinggalah (semasa engkau) kembali kepada Tuhanmu, kemudian engkau tetap menemui balasan apa yang engkau telah usahakan itu (tercatit semuanya)."],[84,7,5891,589,"فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ","Kemudian sesiapa yang diberi menerima surat amalnya dengan tangan kanannya, -"],[84,8,5892,589,"فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا","Maka ia akan dihisab dengan cara yang mudah dan ringan,"],[84,9,5893,589,"وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا","Dan ia akan pergi kepada keluarganya (yang beriman) dengan sukacita."],[84,10,5894,589,"وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ","Dan sesiapa yang diberi menerima surat amalnya (dengan tangan kiri), dari sebelah belakangnya,"],[84,11,5895,589,"فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا","Maka ia akan meraung menyebut-nyebut kebinasaannya,"],[84,12,5896,589,"وَيَصْلَىٰ سَعِيرًا","Dan ia akan menderita bakaran neraka yang marak menjulang."],[84,13,5897,589,"إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا","Sebenarnya ia semasa di dunia dahulu bersukaria dalam kalangan keluarganya (yang juga kufur ingkar)!"],[84,14,5898,589,"إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","Sesungguhnya ia menyangka bahawa ia tidak sekali-kali akan kembali (kepada Kami untuk menerima balasan) !"],[84,15,5899,589,"بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا","(Sangkaannya itu tidak betul) bahkan ia tetap kembali! Sesungguhnya Tuhannya sentiasa Melihat dan Mengetahui keadaannya!"],[84,16,5900,589,"فَلَآ أُقْسِمُ بِٱلشَّفَقِ","Maka Aku bersumpah, demi mega;"],[84,17,5901,589,"وَٱلَّيْلِ وَمَا وَسَقَ","Dan malam serta segala yang dihimpunkannya;"],[84,18,5902,589,"وَٱلْقَمَرِ إِذَا ٱتَّسَقَ","Dan bulan apabila (penuh cahayanya) menjadi purnama:"],[84,19,5903,589,"لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ","Sesungguhnya kamu tetap melalui beberapa keadaan yang bertingkat-tingkat baik buruknya, (sebelum kamu menemui Tuhan - menerima kesenangan dan kebahagiaan atau sebaliknya)"],[84,20,5904,589,"فَمَا لَهُمْ لَا يُؤْمِنُونَ","Maka apakah alasan bagi mereka bersikap tidak mahu beriman?"],[84,21,5905,589,"وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩","Dan (apakah pula alasannya) apabila dibacakan Al-Quran kepada mereka, mereka tidak mahu taat dan sujud?"],[84,22,5906,589,"بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ","(Tidak ada satu alasan pun) bahkan orang-orang yang kafir, semata-mata mendustakannya;"],[84,23,5907,589,"وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ","Sedang Allah mengetahui apa yang mereka rahsiakan dalam hati."],[84,24,5908,589,"فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","Maka khabarkanlah kepada mereka dengan azab yang tidak terperi sakitnya;"],[84,25,5909,589,"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ","Tetapi orang-orang yang beriman dan beramal soleh mereka beroleh pahala balasan yang tidak putus-putus."],[85,1,5910,590,"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ","Demi langit yang mempunyai tempat-tempat peredaran bintang-bintang;"],[85,2,5911,590,"وَٱلْيَوْمِ ٱلْمَوْعُودِ","Dan hari (pembalasan) yang dijanjikan;"],[85,3,5912,590,"وَشَاهِدٍۢ وَمَشْهُودٍۢ","Dan makhluk-makhluk yang hadir menyaksikan hari itu, serta segala keadaan yang disaksikan; -"],[85,4,5913,590,"قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ","Celakalah kaum yang menggali parit,"],[85,5,5914,590,"ٱلنَّارِ ذَاتِ ٱلْوَقُودِ","(Parit) api yang penuh dengan bahan bakaran,"],[85,6,5915,590,"إِذْ هُمْ عَلَيْهَا قُعُودٌۭ","(Mereka dilaknat) ketika mereka duduk di kelilingnya,"],[85,7,5916,590,"وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ","Sambil mereka melihat apa yang mereka lakukan kepada orang-orang yang beriman."],[85,8,5917,590,"وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ","Dan mereka tidak marah dan menyeksakan orang-orang yang beriman itu melainkan kerana orang-orang itu beriman kepada Allah Yang Maha Kuasa, lagi Maha Terpuji!"],[85,9,5918,590,"ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ","Tuhan yang menguasai segala alam langit dan bumi. Dan (ingatlah), Allah sentiasa menyaksikan tiap-tiap sesuatu."],[85,10,5919,590,"إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ","Sesungguhnya orang-orang yang menimpakan bencana untuk memesongkan orang-orang lelaki yang beriman dan orang-orang perempuan yang beriman, kemudian mereka tidak bertaubat, maka mereka akan beroleh azab neraka Jahannam (kerana perbuatan buruk itu), dan mereka akan beroleh lagi azab api yang kuat membakar (kerana mereka tidak bertaubat)."],[85,11,5920,590,"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ","Sesungguhnya orang-orang yang beriman dan beramal soleh, mereka akan beroleh Syurga yang mengalir di bawahnya beberapa sungai; yang demikian itu ialah kemenangan yang besar."],[85,12,5921,590,"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ","Sesungguhnya azab Tuhanmu (terhadap orang-orang yang kufur ingkar) amatlah berat."],[85,13,5922,590,"إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ","Sesungguhnya Dia lah yang menciptakan (sekalian makhluk) pada mulanya, dan yang mengembalikannya (hidup semula sesudah mati)."],[85,14,5923,590,"وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ","Dan Dia lah yang Maha Pengampun, lagi Maha Pengasih."],[85,15,5924,590,"ذُو ٱلْعَرْشِ ٱلْمَجِيدُ","Tuhan yang mempunyai Arasy yang tinggi kemuliaannya,"],[85,16,5925,590,"فَعَّالٌۭ لِّمَا يُرِيدُ","Yang berkuasa melakukan segala yang dikehendakinya."],[85,17,5926,590,"هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ","Sudahkah sampai kepadamu (wahai Muhammad) perihal (kebinasaan yang telah menimpa) kaum-kaum yang menentang (Rasul-rasul yang diutuskan kepada mereka)?"],[85,18,5927,590,"فِرْعَوْنَ وَثَمُودَ","(Mereka itu ialah kaum) Firaun, dan Thamud (kaum Nabi Soleh)."],[85,19,5928,590,"بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍۢ","(Kaummu wahai Muhammad, bukan sahaja menolak ajaranmu), bahkan orang-orang yang kafir itu terus tenggelam dalam keadaan mendustakan kebenaran;"],[85,20,5929,590,"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ","Sedang Allah, dari belakang mereka, melingkungi mereka (dengan kekuasaanNya)!"],[85,21,5930,590,"بَلْ هُوَ قُرْءَانٌۭ مَّجِيدٌۭ","(Sebenarnya apa yang engkau sampaikan kepada mereka bukanlah syair atau sihir), bahkan ialah Al-Quran yang tertinggi kemuliaannya;"],[85,22,5931,590,"فِى لَوْحٍۢ مَّحْفُوظٍۭ","(Lagi yang terpelihara dengan sebaik-baiknya) pada Lauh Mahfuz."],[86,1,5932,591,"وَٱلسَّمَآءِ وَٱلطَّارِقِ","Demi langit dan \"At-Taariq\"; -"],[86,2,5933,591,"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ","Dan apa jalannya engkau dapat mengetahui apa dia \"At-Taariq\" itu? -"],[86,3,5934,591,"ٱلنَّجْمُ ٱلثَّاقِبُ","(At-Taariq) ialah bintang yang menembusi (sinaran cahayanya);"],[86,4,5935,591,"إِن كُلُّ نَفْسٍۢ لَّمَّا عَلَيْهَا حَافِظٌۭ","Tiada sesuatu diri juapun melainkan ada malaikat yang menjaga (keadaannya serta menyimpan catitan mengenai segala bawaannya)."],[86,5,5936,591,"فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ","(Setelah mengetahui yang demikian), maka hendaklah manusia memikirkan: dari apa ia diciptakan."],[86,6,5937,591,"خُلِقَ مِن مَّآءٍۢ دَافِقٍۢ","Ia diciptakan dari air (mani) yang memancut (ke dalam rahim) -"],[86,7,5938,591,"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ","Yang keluar dari \"tulang sulbi\" lelaki dan \"tulang dada\" perempuan."],[86,8,5939,591,"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌۭ","Sesungguhnya Allah Maha Kuasa untuk mengembalikannya (hidup semula sesudah mati),"],[86,9,5940,591,"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ","Pada hari didedahkan segala yang terpendam di hati (dari iktiqad, niat, dan lain-lainnya),"],[86,10,5941,591,"فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ","Maka (pada saat itu) tidak ada bagi manusia sebarang kekuatan (untuk membela diri), dan tidak ada penolong (yang dapat memberikan pertolongan)."],[86,11,5942,591,"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ","Demi langit yang berulang-ulang mencurahkan hujan,"],[86,12,5943,591,"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ","Dan bumi yang merekah mengeluarkan tumbuh-tumbuhan,"],[86,13,5944,591,"إِنَّهُۥ لَقَوْلٌۭ فَصْلٌۭ","Sesungguhnya keterangan Al-Quran adalah kata-kata pemutus (yang sebenar),"],[86,14,5945,591,"وَمَا هُوَ بِٱلْهَزْلِ","Dan bukanlah ia kata-kata yang olok-olok."],[86,15,5946,591,"إِنَّهُمْ يَكِيدُونَ كَيْدًۭا","Sesungguhnya mereka (yang menentangmu, wahai Muhammad) bermati-mati menjalankan rancangan jahat,"],[86,16,5947,591,"وَأَكِيدُ كَيْدًۭا","Dan Aku pula tetap bertindak membalas rancangan jahat (mereka, dan menggagalkannya)."],[86,17,5948,591,"فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا","Oleh itu janganlah engkau hendakkan segera kebinasaan orang-orang kafir itu, berilah tempoh kepada mereka sedikit masa."],[87,1,5949,591,"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى","Bertasbihlah mensucikan nama Tuhanmu Yang Maha Tinggi (dari segala sifat-sifat kekurangan), -"],[87,2,5950,591,"ٱلَّذِى خَلَقَ فَسَوَّىٰ","Yang telah menciptakan (sekalian makhlukNya) serta menyempurnakan kejadiannya dengan kelengkapan yang sesuai dengan keadaannya;"],[87,3,5951,591,"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","Dan Yang telah mengatur (keadaan makhluk-makhlukNya) serta memberikan hidayah petunjuk (ke jalan keselamatannya dan kesempurnaannya);"],[87,4,5952,591,"وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ","Dan Yang telah mengeluarkan tumbuh-tumbuhan untuk binatang-binatang ternak,"],[87,5,5953,591,"فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ","Kemudian Ia menjadikan (tumbuh-tumbuhan yang menghijau) itu kering - (berubah warnanya) kehitam-hitaman."],[87,6,5954,591,"سَنُقْرِئُكَ فَلَا تَنسَىٰٓ","Kami sentiasa menjadikan engkau (wahai Muhammad) dapat membaca (Al-Quran yang diturunkan kepadamu - dengan perantaraan jibril), sehingga engkau (menghafaznya dan) tidak lupa,"],[87,7,5955,591,"إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","Kecuali apa yang dikehendaki Allah engkau lupakan; sesungguhnya Ia mengetahui (segala keadaan yang patut berlaku), dan yang tersembunyi."],[87,8,5956,591,"وَنُيَسِّرُكَ لِلْيُسْرَىٰ","Dan Kami tetap memberi kemudahan kepadamu untuk (melaksanakan segala perkara) Ugama yang mudah diterima oleh akal yang sihat."],[87,9,5957,591,"فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ","Oleh itu berilah peringatan (kepada umat manusia dengan ajaran Al-Quran), kalau-kalau peringatan itu berguna (dan sudah tentu berguna);"],[87,10,5958,591,"سَيَذَّكَّرُ مَن يَخْشَىٰ","Kerana orang yang takut (melanggar perintah Allah) akan menerima peringatan itu;"],[87,11,5959,591,"وَيَتَجَنَّبُهَا ٱلْأَشْقَى","Dan (sebaliknya) orang yang sangat celaka akan menjauhinya,"],[87,12,5960,591,"ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ","Dia lah orang yang akan menderita bakaran neraka yang amat besar (azab seksanya),"],[87,13,5961,591,"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","Selain dari itu, ia tidak mati di dalamnya dan tidak pula hidup senang."],[87,14,5962,591,"قَدْ أَفْلَحَ مَن تَزَكَّىٰ","Sesungguhnya berjayalah orang yang - setelah menerima peringatan itu - berusaha membersihkan dirinya (dengan taat dan amal yang soleh),"],[87,15,5963,591,"وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ","Dan menyebut-nyebut dengan lidah dan hatinya akan nama Tuhannya serta mangerjakan sembahyang (dengan khusyuk)."],[87,16,5964,592,"بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","(Tetapi kebanyakkan kamu tidak melakukan yang demikian), bahkan kamu utamakan kehidupan dunia;"],[87,17,5965,592,"وَٱلْءَاخِرَةُ خَيْرٌۭ وَأَبْقَىٰٓ","Padahal kehidupan akhirat lebih baik dan lebih kekal."],[87,18,5966,592,"إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ","Sesungguhnya (keterangan-keterangan yang dinyatakan) ini ada (disebutkan) di dalam Kitab-kitab yang terdahulu, -"],[87,19,5967,592,"صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ","Iaitu Kitab-kitab Nabi Ibrahim dan Nabi Musa."],[88,1,5968,592,"هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ","Sudahkah sampai kepadamu (wahai Muhammad) perihal hari kiamat yang huru-haranya meliputi?"],[88,2,5969,592,"وُجُوهٌۭ يَوْمَئِذٍ خَٰشِعَةٌ","Muka (orang-orang yang kafir) pada hari itu tunduk kerana merasa hina,"],[88,3,5970,592,"عَامِلَةٌۭ نَّاصِبَةٌۭ","Mereka menjalankan kerja yang berat lagi berpenat lelah,"],[88,4,5971,592,"تَصْلَىٰ نَارًا حَامِيَةًۭ","Mereka tetap menderita bakaran neraka yang amat panas (membakar), -"],[88,5,5972,592,"تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍۢ","Mereka diberi minum dari matair yang menggelegak panasnya."],[88,6,5973,592,"لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍۢ","Tiada makanan bagi mereka (di situ) selain dari pokok-pokok yang berduri,"],[88,7,5974,592,"لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍۢ","Yang tidak menggemokkan, dan tidak pula dapat menghilangkan sedikit kelaparan pun."],[88,8,5975,592,"وُجُوهٌۭ يَوْمَئِذٍۢ نَّاعِمَةٌۭ","(Sebaliknya) muka (orang-orang yang beriman) pada hari itu berseri-seri,"],[88,9,5976,592,"لِّسَعْيِهَا رَاضِيَةٌۭ","Berpuas hati dengan balasan amal usahanya (yang baik yang telah dikerjakannya di dunia), -"],[88,10,5977,592,"فِى جَنَّةٍ عَالِيَةٍۢ","(Mereka tinggal menetap) di dalam Syurga tinggi (tempat kedudukannya darjatnya),"],[88,11,5978,592,"لَّا تَسْمَعُ فِيهَا لَٰغِيَةًۭ","Mereka tidak mendengar di situ sebarang perkataan yang sia-sia,"],[88,12,5979,592,"فِيهَا عَيْنٌۭ جَارِيَةٌۭ","Di dalam Syurga itu ada matair yang mengalir,"],[88,13,5980,592,"فِيهَا سُرُرٌۭ مَّرْفُوعَةٌۭ","Di situ juga ada pelamin-pelamin (berhias) yang tinggi (tempatnya),"],[88,14,5981,592,"وَأَكْوَابٌۭ مَّوْضُوعَةٌۭ","Dan piala-piala minuman yang disediakan (untuk mereka),"],[88,15,5982,592,"وَنَمَارِقُ مَصْفُوفَةٌۭ","Dan bantal-bantal yang teratur (untuk mereka berbaring atau bersandar),"],[88,16,5983,592,"وَزَرَابِىُّ مَبْثُوثَةٌ","Serta hamparan-hamparan yang terbentang."],[88,17,5984,592,"أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ","(Mengapa mereka yang kafir masih mengingkari akhirat) tidakkah mereka memperhatikan keadaan unta bagaimana ia diciptakan?"],[88,18,5985,592,"وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ","Dan keadaan langit bagaimana ia ditinggikan binaannya.?"],[88,19,5986,592,"وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ","Dan keadaan gunung-ganang bagaimana ia ditegakkan?"],[88,20,5987,592,"وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ","Dan keadaan bumi bagaimana ia dihamparkan?"],[88,21,5988,592,"فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌۭ","Oleh itu berikanlah sahaja peringatan (wahai Muhammad, kepada manusia, dan janganlah berdukacita kiranya ada yang menolaknya), kerana sesungguhnya engkau hanyalah seorang Rasul pemberi ingatan;"],[88,22,5989,592,"لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ","Bukanlah engkau seorang yang berkuasa memaksa mereka (menerima ajaran Islam yang engkau sampaikan itu)."],[88,23,5990,592,"إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","Akan tetapi sesiapa yang berpaling (dari kebenaran) serta ia kufur ingkar, -"],[88,24,5991,592,"فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ","Maka Allah akan menyeksanya dengan azab seksa yang sebesar-besarnya."],[88,25,5992,592,"إِنَّ إِلَيْنَآ إِيَابَهُمْ","Sesungguhnya kepada Kamilah kembalinya mereka,"],[88,26,5993,592,"ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم","Selain dari itu, sesungguhnya tanggungan Kamilah soal menghitung amal mereka."],[89,1,5994,593,"وَٱلْفَجْرِ","Demi waktu fajar;"],[89,2,5995,593,"وَلَيَالٍ عَشْرٍۢ","Dan malam yang sepuluh (yang mempunyai kelebihan di sisi Allah);"],[89,3,5996,593,"وَٱلشَّفْعِ وَٱلْوَتْرِ","Dan bilangan yang genap serta yang ganjil;"],[89,4,5997,593,"وَٱلَّيْلِ إِذَا يَسْرِ","Dan malam, apabila ia berlalu; -"],[89,5,5998,593,"هَلْ فِى ذَٰلِكَ قَسَمٌۭ لِّذِى حِجْرٍ","Bukankah yang demikian itu mengandungi sumpah (yang diakui kebenarannya) oleh orang yang berakal sempurna?"],[89,6,5999,593,"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","(Kami tetap akan membinasakan orang-orang yang menentangmu wahai Muhammad), tidakkah engkau perhatikan, bagaimana Tuhanmu telah melakukan terhadap kaum Aad (yang kufur derhaka)"],[89,7,6000,593,"إِرَمَ ذَاتِ ٱلْعِمَادِ","Iaitu penduduk \"Iram\" yang mempunyai bangunan-bangunan yang tinggi tiangnya, (sesuai dengan penduduknya)"],[89,8,6001,593,"ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ","Yang belum pernah diciptakan sepertinya (tentang besar dan kukuhnya) di segala negeri (pada zamannya)?"],[89,9,6002,593,"وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ","Dan (terhadap) kaum Thamud yang memahat batu-batu besar di lembah (Wadil-Qura iaitu tempat tinggalnya)?"],[89,10,6003,593,"وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ","Dan (terhadap) Firaun yang menguasai bangunan-bangunan yang handal kukuh?"],[89,11,6004,593,"ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ","(Semuanya itu ialah) orang-orang yang telah bermaharajalela di negeri (masing-masing)."],[89,12,6005,593,"فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ","Lalu mereka melakukan dengan banyaknya kerosakan dan bencana di negeri-negeri itu."],[89,13,6006,593,"فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ","Dengan yang demikian, Tuhanmu mencurahkan ke atas mereka berbagai paluan azab;"],[89,14,6007,593,"إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ","Sesungguhnya Tuhanmu tetap mengawas dan membalas, (terutama balasan akhirat)"],[89,15,6008,593,"فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ","(Dalam pada itu manusia tidak menghiraukan balasan akhirat), oleh yang demikian, maka kebanyakan manusia apabila diuji oleh Tuhannya dengan dimuliakan dan dimewahkan hidupnya, (ia tidak mahu bersyukur tetapi terus bersikap takbur) serta berkata dengan sombongnya: \"Tuhanku telah memuliakan daku!\""],[89,16,6009,593,"وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ","Dan sebaliknya apabila ia diuji oleh Tuhannya, dengan disempitkan rezekinya, (ia tidak bersabar bahkan ia resah gelisah) serta merepek dengan katanya: \"Tuhanku telah menghinakan daku!\""],[89,17,6010,593,"كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ","Jangan demikian, (sebenarnya kata-kata kamu itu salah). Bahkan (perbuatan kamu wahai orang-orang yang hidup mewah, lebih salah lagi kerana) kamu tidak memuliakan anak yatim, (malah kamu menahan apa yang Ia berhak menerimanya);"],[89,18,6011,593,"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","Dan kamu tidak menggalakkan untuk memberi makanan (yang berhak diterima oleh) orang miskin;"],[89,19,6012,593,"وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًۭا لَّمًّۭا","Dan kamu sentiasa makan harta pusaka secara rakus (dengan tidak membezakan halal haramnya),"],[89,20,6013,593,"وَتُحِبُّونَ ٱلْمَالَ حُبًّۭا جَمًّۭا","Serta kamu pula sayangkan harta secara tamak haloba!"],[89,21,6014,593,"كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا","Jangan sekali-kali bersikap demikian! (Sebenarnya) apabila bumi (dihancurkan segala yang ada di atasnya dan) diratakan serata-ratanya,"],[89,22,6015,593,"وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا","Dan (perintah) Tuhanmu pun datang, sedang malaikat berbaris-baris (siap sedia menjalankan perintah),"],[89,23,6016,593,"وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ","Serta diperlihatkan neraka Jahannam pada hari itu, (maka) pada saat itu manusia akan ingat (hendak berlaku baik), dan bagaimana ingatan itu akan berguna lagi kepadanya?"],[89,24,6017,594,"يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى","Ia akan berkata: \"Alangkah baiknya kalau aku dahulu sediakan amal-amal baik untuk hidupku (di sini)!\""],[89,25,6018,594,"فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ","Maka pada hari itu tiada sesiapapun yang dapat menyeksa seperti azab (yang ditimpakan oleh) Allah."],[89,26,6019,594,"وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ","Dan tiada sesiapapun yang dapat mengikat serta membelenggu seperti ikatan dan belengguNya."],[89,27,6020,594,"يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ","(Setelah menerangkan akibat orang-orang yang tidak menghiraukan akhirat, Tuhan menyatakan bahawa orang-orang yang beriman dan beramal soleh akan disambut dengan kata-kata): \"Wahai orang yang mempunyai jiwa yang sentiasa tenang tetap dengan kepercayaan dan bawaan baiknya! -"],[89,28,6021,594,"ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ","\"Kembalilah kepada Tuhanmu dengan keadaan engkau berpuas hati (dengan segala nikmat yang diberikan) lagi diredhai (di sisi Tuhanmu) ! -"],[89,29,6022,594,"فَٱدْخُلِى فِى عِبَٰدِى","\"Serta masuklah engkau dalam kumpulan hamba-hambaku yang berbahagia -"],[89,30,6023,594,"وَٱدْخُلِى جَنَّتِى","\"Dan masuklah ke dalam SyurgaKu! \""],[90,1,6024,594,"لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ","Aku bersumpah dengan negeri (Makkah) ini;"],[90,2,6025,594,"وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ","Sedang engkau (wahai Muhammad) tinggal di negeri ini (sentiasa ditindas),"],[90,3,6026,594,"وَوَالِدٍۢ وَمَا وَلَدَ","Demi manusia yang melahirkan zuriat, dan zuriat yang dilahirkannya;"],[90,4,6027,594,"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ","Sesungguhnya Kami telah jadikan manusia sentiasa dalam keadaan menghadapi kesulitan dan kesukaran (jasmani dan rohaninya);"],[90,5,6028,594,"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ","Patutkah manusia yang demikian keadaannya (terpedaya dengan kekuasaan yang ada padanya dan) menyangka bahawa tidak ada sesiapapun yang dapat mengatasi kekuasaannya (dan menyeksakannya)?"],[90,6,6029,594,"يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا","Manusia yang demikian keadaannya (tidaklah patut ia bermegah-megah dengan kekayaannya dan) berkata: \"Aku telah habiskan harta benda yang banyak (dalam usaha menegakkan nama dan bangsa)."],[90,7,6030,594,"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ","Adakah ia menyangka bahawa tidak ada sesiapapun yang melihatnya (dan mengetahui tujuannya menghabiskan harta bendanya itu?"],[90,8,6031,594,"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","(Mengapa manusia terpedaya dan bermegah-megah?) Tidakkah Kami telah menjadikan baginya: dua mata (untuk ia memerhatikan kekuasaan dan kekayaan Kami?) -"],[90,9,6032,594,"وَلِسَانًۭا وَشَفَتَيْنِ","Dan lidah serta dua bibir (untuk ia menyempurnakan sebahagian besar dari hajat-hajatnya)?"],[90,10,6033,594,"وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ","Dan Kami telah menunjukkan kepadanya dua jalan, (jalan kebaikan untuk dijalaninya, dan jalan kejahatan untuk dijauhi)?"],[90,11,6034,594,"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ","Dalam pada itu manusia tidak (memilih jalan kebaikan) merempuh masuk mengerjakan amal-amal yang tinggi darjatnya di sisi Tuhan;"],[90,12,6035,594,"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ","Dan apa jalannya engkau dapat mengetahui: apa dia amal-amal yang tinggi darjatnya di sisi Tuhan itu?"],[90,13,6036,594,"فَكُّ رَقَبَةٍ","(Di antara amal-amal itu - bagi orang yang mampu) ialah: memerdekakan hamba abdi;"],[90,14,6037,594,"أَوْ إِطْعَٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ","Atau memberi makan pada hari kelaparan -"],[90,15,6038,594,"يَتِيمًۭا ذَا مَقْرَبَةٍ","Kepada anak yatim dari kaum kerabat,"],[90,16,6039,594,"أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ","Atau kepada orang miskin yang terlantar di atas tanah."],[90,17,6040,594,"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","Selain dari (tidak mengerjakan amal-amal) itu, ia (tidak pula) menjadi dari orang-orang yang beriman dan berpesan-pesan dengan sabar serta berpesan-pesan dengan kasih sayang."],[90,18,6041,594,"أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ","(Ketahuilah! Bahawa orang-orang yang beriman serta berusaha mengerjakan amal-amal yang tinggi darjatnya di sisi Tuhan), merekalah golongan pihak kanan (yang akan beroleh Syurga)."],[90,19,6042,594,"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ","Dan (sebaliknya) orang-orang yang kufur ingkar akan ayat-ayat keterangan Kami, merekalah golongan pihak kiri. -"],[90,20,6043,594,"عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ","Mereka ditimpakan (azab seksa) neraka yang ditutup rapat (supaya kuat bakarannya)."],[91,1,6044,595,"وَٱلشَّمْسِ وَضُحَىٰهَا","Demi matahari dan cahayanya yang terang-benderang;"],[91,2,6045,595,"وَٱلْقَمَرِ إِذَا تَلَىٰهَا","Dan bulan apabila ia mengiringinya;"],[91,3,6046,595,"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","Dan siang apabila ia memperlihatkannya dengan jelas nyata;"],[91,4,6047,595,"وَٱلَّيْلِ إِذَا يَغْشَىٰهَا","Dan malam apabila ia menyelubunginya (dengan gelap- gelita),"],[91,5,6048,595,"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","Demi langit dan Yang membinanya (dalam bentuk yang kuat kukuh - yang melambangkan kekuasaanNya);"],[91,6,6049,595,"وَٱلْأَرْضِ وَمَا طَحَىٰهَا","Serta bumi dan Yang menghamparkannya (untuk kemudahan makhluk-makhlukNya);"],[91,7,6050,595,"وَنَفْسٍۢ وَمَا سَوَّىٰهَا","Demi diri manusia dan Yang menyempurnakan kejadiannya (dengan kelengkapan yang sesuai dengan keadaannya);"],[91,8,6051,595,"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا","Serta mengilhamkannya (untuk mengenal) jalan yang membawanya kepada kejahatan, dan yang membawanya kepada bertaqwa; -"],[91,9,6052,595,"قَدْ أَفْلَحَ مَن زَكَّىٰهَا","Sesungguhnya berjayalah orang yang menjadikan dirinya - yang sedia bersih - bertambah-tambah bersih (dengan iman dan amal kebajikan),"],[91,10,6053,595,"وَقَدْ خَابَ مَن دَسَّىٰهَا","Dan sesungguhnya hampalah orang yang menjadikan dirinya - yang sedia bersih - itu susut dan terbenam kebersihannya (dengan sebab kekotoran maksiat)."],[91,11,6054,595,"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","(Ingatlah), kaum Thamud telah mendustakan (Rasulnya) dengan sebab perbuatan derhaka mereka yang melampaui batas;"],[91,12,6055,595,"إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا","Ketika orang yang paling jahat di antara mereka menerima perintah dari mereka (supaya membunuh unta yang menjadi mukjizat),"],[91,13,6056,595,"فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا","Maka berkatalah Rasul Allah (Nabi Soleh) kepada mereka: \" (Janganlah kamu ganggu) unta betina dari Allah itu, dan (janganlah kamu menyekatnya daripada mendapat) air minumnya (supaya kamu tidak ditimpa azab)!\""],[91,14,6057,595,"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا","(Setelah Nabi Soleh memberi amaran) lalu mereka mendustakannya serta menyembelih unta itu. Dengan sebab dosa mereka, maka Tuhan menimpakan mereka dengan azab yang membinasakan serta Ia meratakan azab itu meliputi mereka (sehingga punah-ranah semuanya)."],[91,15,6058,595,"وَلَا يَخَافُ عُقْبَٰهَا","Dan Allah tidak hiraukan kesudahan (mereka) yang demikian, (kerana itu adalah balasan yang adil)."],[92,1,6059,595,"وَٱلَّيْلِ إِذَا يَغْشَىٰ","Demi malam apabila ia menyelubungi segala-galanya (dengan gelap-gelitanya),"],[92,2,6060,595,"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","Dan siang apabila ia lahir terang-benderang;"],[92,3,6061,595,"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ","Demi Yang menciptakan (makhluk-makhlukNya) lelaki dan perempuan, (jantan dan betina); -"],[92,4,6062,595,"إِنَّ سَعْيَكُمْ لَشَتَّىٰ","Sesungguhnya amal usaha kamu adalah berbagai-bagai keadaannya."],[92,5,6063,595,"فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ","Jelasnya: adapun orang yang memberikan apa yang ada padanya ke jalan kebaikan dan bertaqwa (mengerjakan suruhan Allah dan meninggalkan segala laranganNya), -"],[92,6,6064,595,"وَصَدَّقَ بِٱلْحُسْنَىٰ","Serta ia mengakui dengan yakin akan perkara yang baik,"],[92,7,6065,595,"فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ","Maka sesungguhnya Kami akan memberikannya kemudahan untuk mendapat kesenangan (Syurga)."],[92,8,6066,595,"وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ","Sebaliknya: orang yang bakhil (daripada berbuat kebajikan) dan merasa cukup dengan kekayaan dan kemewahannya, -"],[92,9,6067,595,"وَكَذَّبَ بِٱلْحُسْنَىٰ","Serta ia mendustakan perkara yang baik,"],[92,10,6068,595,"فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ","Maka sesungguhnya Kami akan memberikannya kemudahan untuk mendapat kesusahan dan kesengsaraan;"],[92,11,6069,595,"وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","Dan apakah pertolongan yang dapat diberi kepadanya oleh hartanya apabiha ia telah terjerumus (ke dalam azab seksa hari akhirat)?"],[92,12,6070,595,"إِنَّ عَلَيْنَا لَلْهُدَىٰ","Sesungguhnya tanggungan Kamilah memberi hidayah petunjuk (tentang yang benar dan yang salah)."],[92,13,6071,595,"وَإِنَّ لَنَا لَلْءَاخِرَةَ وَٱلْأُولَىٰ","Dan sesungguhnya Kamilah yang menguasai hari akhirat dan alam dunia."],[92,14,6072,595,"فَأَنذَرْتُكُمْ نَارًۭا تَلَظَّىٰ","Maka (serentak dengan memberi hidayah petunjuk) Aku juga telah memberi amaran mengingatkan kamu akan api neraka yang marak menjulang,"],[92,15,6073,596,"لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى","Yang tidak akan menderita bakarannya melainkan orang yang sungguh celaka, -"],[92,16,6074,596,"ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","Yang telah mendustakan (kebenaran) dan berpaling ingkar."],[92,17,6075,596,"وَسَيُجَنَّبُهَا ٱلْأَتْقَى","Dan (sebaliknya) akan dijauhkan (azab neraka) itu daripada orang yang sungguh bertaqwa, -"],[92,18,6076,596,"ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ","Yang mendermakan hartanya dengan tujuan membersihkan dirinya dan hartabendanya,"],[92,19,6077,596,"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍۢ تُجْزَىٰٓ","Sedang ia tidak menanggung budi sesiapapun, yang patut di balas,"],[92,20,6078,596,"إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ","Hanyalah mengharapkan keredaan Tuhannya Yang Maha Tinggi;"],[92,21,6079,596,"وَلَسَوْفَ يَرْضَىٰ","Dan demi sesungguhnya, ia tetap akan berpuas hati (pada hari akhirat, dengan mendapat segala yang diharapkannya)."],[93,1,6080,596,"وَٱلضُّحَىٰ","Demi waktu dhuha,"],[93,2,6081,596,"وَٱلَّيْلِ إِذَا سَجَىٰ","Dan malam apabila ia sunyi-sepi -"],[93,3,6082,596,"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","(Bahawa) Tuhanmu (wahai Muhammad) tidak meninggalkanmu, dan Ia tidak benci (kepadamu, sebagaimana yang dituduh oleh kaum musyrik)."],[93,4,6083,596,"وَلَلْءَاخِرَةُ خَيْرٌۭ لَّكَ مِنَ ٱلْأُولَىٰ","Dan sesungguhnya kesudahan keaadaanmu adalah lebih baik bagimu daripada permulaannya."],[93,5,6084,596,"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","Dan sesungguhnya Tuhanmu akan memberikanmu (kejayaan dan kebahagiaan di dunia dan di akhirat) sehingga engkau reda - berpuas hati."],[93,6,6085,596,"أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ","Bukankah dia mendapati engkau yatim piatu, lalu la memberikan perlindungan?"],[93,7,6086,596,"وَوَجَدَكَ ضَآلًّۭا فَهَدَىٰ","Dan didapatiNya engkau mencari-cari (jalan yang benar), lalu Ia memberikan hidayah petunjuk (dengan wahyu - Al-Quran)?"],[93,8,6087,596,"وَوَجَدَكَ عَآئِلًۭا فَأَغْنَىٰ","Dan didapatiNya engkau miskin, lalu Ia memberikan kekayaan?"],[93,9,6088,596,"فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ","Oleh itu, adapun anak yatim maka janganlah engkau berlaku kasar terhadapnya,"],[93,10,6089,596,"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ","Adapun orang yang meminta (bantuan pimpinan) maka janganlah engkau tengking herdik;"],[93,11,6090,596,"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","Adapun nikmat Tuhanmu, maka hendaklah engkau sebut-sebutkan (dan zahirkan) sebagai bersyukur kepadaNya."],[94,1,6091,596,"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","Bukankah Kami telah melapangkan bagimu: dadamu (wahai Muhammad serta mengisinya dengan iman dan hidayah petunjuk) ?"],[94,2,6092,596,"وَوَضَعْنَا عَنكَ وِزْرَكَ","Dan Kami telah meringankan daripadamu: bebanmu (menyiarkan Islam) -"],[94,3,6093,596,"ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ","Yang memberati tanggunganmu, (dengan memberikan berbagai kemudahan dalam melaksanakannya)?"],[94,4,6094,596,"وَرَفَعْنَا لَكَ ذِكْرَكَ","Dan Kami telah meninggikan bagimu: sebutan namamu (dengan mengurniakan pangkat Nabi dan berbagai kemuliaan)?"],[94,5,6095,596,"فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا","Oleh itu, maka (tetapkanlah kepercayaanmu) bahawa sesungguhnya tiap-tiap kesukaran disertai kemudahan,"],[94,6,6096,596,"إِنَّ مَعَ ٱلْعُسْرِ يُسْرًۭا","(Sekali lagi ditegaskan): bahawa sesungguhnya tiap-tiap kesukaran disertai kemudahan."],[94,7,6097,596,"فَإِذَا فَرَغْتَ فَٱنصَبْ","Kemudian apabila engkau telah selesai (daripada sesuatu amal soleh), maka bersungguh-sungguhlah engkau berusaha (mengerjakan amal soleh yang lain),"],[94,8,6098,596,"وَإِلَىٰ رَبِّكَ فَٱرْغَب","Dan kepada Tuhanmu sahaja hendaklah engkau memohon (apa yang engkau gemar dan ingini)."],[95,1,6099,597,"وَٱلتِّينِ وَٱلزَّيْتُونِ","Demi buah Tiin dan Zaitun,"],[95,2,6100,597,"وَطُورِ سِينِينَ","Dan Gunung Tursina,"],[95,3,6101,597,"وَهَٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","Serta negeri (Makkah) yang aman ini, -"],[95,4,6102,597,"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍۢ","Sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya (dan berkelengkapan sesuai dengan keadaannya)."],[95,5,6103,597,"ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ","Kemudian (jika ia panjang umur sehingga tua atau menyalahgunakan kelengkapan itu), Kami kembalikan dia ke serendah-rendah peringkat orang-orang yang rendah,"],[95,6,6104,597,"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ","Kecuali orang-orang yang beriman dan beramal soleh, maka mereka beroleh pahala yang tidak putus-putus."],[95,7,6105,597,"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","(Jika demikian kekuasaanKu), maka apa pula yang menjadikan engkau seorang pendusta, (berkata tidak benar) mengenai hari pembalasan, sesudah (ternyata dalil-dalil yang membuktikan kekuasaanKu mengadakan hari pembalasan) itu?"],[95,8,6106,597,"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَٰكِمِينَ","Bukankah Allah (yang demikian kekuasaanNya) seadil-adil Hakim?"],[96,1,6107,597,"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ","Bacalah (wahai Muhammad) dengan nama Tuhanmu yang menciptakan (sekalian makhluk),"],[96,2,6108,597,"خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ","Ia menciptakan manusia dari sebuku darah beku;"],[96,3,6109,597,"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ","Bacalah, dan Tuhanmu Yang Maha Pemurah, -"],[96,4,6110,597,"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ","Yang mengajar manusia melalui pena dan tulisan, -"],[96,5,6111,597,"عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ","Ia mengajarkan manusia apa yang tidak diketahuinya."],[96,6,6112,597,"كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ","Ingatlah! Sesungguhnya jenis manusia tetap melampaui batas (yang sepatutnya atau yang sewajibnya),"],[96,7,6113,597,"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ","Dengan sebab ia melihat dirinya sudah cukup apa yang dihajatinya."],[96,8,6114,597,"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ","(Ingatlah) sesungguhnya kepada Tuhanmu lah tempat kembali (untuk menerima balasan)."],[96,9,6115,597,"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","Adakah engkau nampak (baiknya) orang yang melarang (dan menghalang) -"],[96,10,6116,597,"عَبْدًا إِذَا صَلَّىٰٓ","Seorang hamba Allah apabila ia mengerjakan sembahyang?"],[96,11,6117,597,"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","Adakah engkau nampak (buruknya) jika ia berada di atas jalan yang betul? -"],[96,12,6118,597,"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","Atau ia menyuruh orang bertaqwa (jangan melakukan syirik)?"],[96,13,6119,597,"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","Adakah engkau nampak (terlepasnya dari azab) jika ia mendustakan (apa yang disampaikan oleh Nabi Muhammad kepadanya) serta ia berpaling ingkar?"],[96,14,6120,597,"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ","Tidakkah ia mengetahui bahawa sesungguhnya Allah melihat (segala amal perbuatannya dan membalasnya)?"],[96,15,6121,597,"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ","Jangan sekali-kali berlaku derhaka! Demi sesungguhnya jika ia tidak berhenti (dari perbuatannya yang buruk itu), nescaya Kami akan menyentap ubun-ubunnya (dan menyeretnya ke dalam neraka), -"],[96,16,6122,597,"نَاصِيَةٍۢ كَٰذِبَةٍ خَاطِئَةٍۢ","Ubun-ubun (orang) yang berdusta, yang bersalah."],[96,17,6123,597,"فَلْيَدْعُ نَادِيَهُۥ","Kemudian biarlah ia memanggil kumpulannya (untuk menyelamatkannya),"],[96,18,6124,597,"سَنَدْعُ ٱلزَّبَانِيَةَ","Kami pula akan memanggil malaikat Zabaniyah (untuk menyeksanya)!"],[96,19,6125,597,"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩","Ingatlah! Janganlah engkau (wahai Muhammad) menurut kehendaknya, dan (sebaliknya) sujudlah dan dampingkanlah dirimu kepada Allah (dengan taat dan beramal soleh)!"],[97,1,6126,598,"إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ","Sesungguhnya Kami telah menurunkan (Al-Quran) ini pada Malam Lailatul-Qadar,"],[97,2,6127,598,"وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ","Dan apa jalannya engkau dapat mengetahui apa dia kebesaran Malam Lailatul-Qadar itu?"],[97,3,6128,598,"لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ","Malam Lailatul-Qadar lebih baik daripada seribu bulan."],[97,4,6129,598,"تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ","Pada Malam itu, turun malaikat dan Jibril dengan izin Tuhan mereka, kerana membawa segala perkara (yang ditakdirkan berlakunya pada tahun yang berikut);"],[97,5,6130,598,"سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ","Sejahteralah Malam (yang berkat) itu hingga terbit fajar!"],[98,1,6131,598,"لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ","Orang-orang yang kafir dari Ahli Kitab (Yahudi dan Nasrani) serta orang-orang musyrik, tidak akan terlepas (dari kepercayaan dan amalan masing-masing) sehingga datang kepada mereka bukti yang jelas nyata, -"],[98,2,6132,598,"رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ","Iaitu seorang Rasul dari Allah yang membacakan (kepada mereka) Lembaran-lembaran Suci,"],[98,3,6133,598,"فِيهَا كُتُبٌۭ قَيِّمَةٌۭ","Terkandung di dalamnya pelajaran-pelajaran dan hukum-hukum yang benar."],[98,4,6134,598,"وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ","Dan orang-orang (Yahudi dan Nasrani) yang diberi Kitab (Taurat dan Injil) itu, tidak berpecah-belah melainkan setelah datang kepada mereka bukti yang jelas nyata."],[98,5,6135,598,"وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ","Pada hal mereka tidak diperintahkan melainkan supaya menyembah Allah dengan mengikhlaskan ibadat kepadaNya, lagi tetap teguh di atas tauhid; dan supaya mereka mendirikan sembahyang serta memberi zakat. Dan yang demikian itulah Ugama yang benar."],[98,6,6136,598,"إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ ۚ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ","Sesungguhnya orang-orang yang kafir dari Ahli Kitab dan orang-orang musyrik itu akan ditempatkan di dalam neraka Jahannam, kekalah mereka di dalamnya. Mereka itulah sejahat-jahat makhluk."],[98,7,6137,598,"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ","Seungguhnya orang-orang yang beriman dan beramal soleh, mereka itulah sebaik-baik makhluk."],[98,8,6138,599,"جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ","Balasan mereka di sisi Tuhannya ialah syurga Adn (tempat tinggal yang tetap), yang mengalir di bawahnya beberapa sungai; kekalah mereka di dalamnya selama-lamanya; Allah reda akan mereka dan merekapun reda (serta bersyukur) akan nikmat pemberianNya. Balasan yang demikian itu untuk orang-orang yang takut (melanggar perintah) Tuhannya."],[99,1,6139,599,"إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","Apabila bumi digegarkan dengan gegaran yang sedahsyat-dahsyatnya,"],[99,2,6140,599,"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","Serta bumi itu mengeluarkan segala isinya,"],[99,3,6141,599,"وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا","Dan berkatalah manusia (dengan perasaan gerun); \"Apa yang sudah terjadi kepada bumi?\""],[99,4,6142,599,"يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا","Pada hari itu bumipun menceritakan khabar beritanya:"],[99,5,6143,599,"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","Bahawa Tuhanmu telah memerintahnya (berlaku demikian)."],[99,6,6144,599,"يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَٰلَهُمْ","Pada hari itu manusia akan keluar berselerak (dari kubur masing-masing) - untuk diperlihatkan kepada mereka (balasan) amal-amal mereka."],[99,7,6145,599,"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ","Maka sesiapa berbuat kebajikan seberat zarah, nescaya akan dilihatnya (dalam surat amalnya)!"],[99,8,6146,599,"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ","Dan sesiapa berbuat kejahatan seberat zarah, nescaya akan dilihatnya (dalam surat amalnya)!"],[100,1,6147,599,"وَٱلْعَٰدِيَٰتِ ضَبْحًۭا","Demi Kuda Perang yang tangkas berlari dengan kedengaran kencang nafasnya,"],[100,2,6148,599,"فَٱلْمُورِيَٰتِ قَدْحًۭا","Serta mencetuskan api dari telapak kakinya,"],[100,3,6149,599,"فَٱلْمُغِيرَٰتِ صُبْحًۭا","Dan meluru menyerbu musuh pada waktu subuh,"],[100,4,6150,599,"فَأَثَرْنَ بِهِۦ نَقْعًۭا","Sehingga menghamburkan debu pada waktu itu,"],[100,5,6151,599,"فَوَسَطْنَ بِهِۦ جَمْعًا","Lalu menggempur ketika itu di tengah-tengah kumpulan musuh;"],[100,6,6152,599,"إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌۭ","Sesungguhnya manusia sangat tidak bersyukur akan nikmat Tuhannya."],[100,7,6153,599,"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ","Dan sesungguhnya ia (dengan bawaannya) menerangkan dengan jelas keadaan yang demikian;"],[100,8,6154,599,"وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ","Dan sesungguhnya ia melampau sangat sayangkan harta (secara tamak haloba)."],[100,9,6155,599,"۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ","(Patutkah ia bersikap demikian?) Tidakkah ia mengetahui (bagaimana keadaan) ketika dibongkarkan segala yang ada dalam kubur?"],[100,10,6156,600,"وَحُصِّلَ مَا فِى ٱلصُّدُورِ","Dan dikumpul serta didedahkan segala yang terpendam dalam dada?"],[100,11,6157,600,"إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ","Sesungguhnya Tuhan mereka Maha Mengetahui dengan mendalam tentang (balasan yang diberikanNya kepada) mereka - pada hari itu."],[101,1,6158,600,"ٱلْقَارِعَةُ","Hari yang menggemparkan,"],[101,2,6159,600,"مَا ٱلْقَارِعَةُ","Apa dia hari yang menggemparkan itu?"],[101,3,6160,600,"وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ","Dan apa jalannya engkau dapat mengetahui kedahsyatan hari yang menggemparkan itu? -"],[101,4,6161,600,"يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ","(Hari itu ialah: hari kiamat), hari manusia menjadi seperti kelkatu yang terbang berkeliaran,"],[101,5,6162,600,"وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ","Dan gunung-ganang menjadi seperti bulu yang dibusar berterbangan."],[101,6,6163,600,"فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ","Setelah berlaku demikian, maka (manusia akan diberikan tempatnya menurut amal masing-masing); adapun orang yang berat timbangan amal baiknya, -"],[101,7,6164,600,"فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ","Maka ia berada dalam kehidupan yang senang lenang."],[101,8,6165,600,"وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ","Sebaliknya orang yang ringan timbangan amal baiknya, -"],[101,9,6166,600,"فَأُمُّهُۥ هَاوِيَةٌۭ","Maka tempat kembalinya ialah \"Haawiyah\""],[101,10,6167,600,"وَمَآ أَدْرَىٰكَ مَا هِيَهْ","Dan apa jalannya engkau dapat mengetahui, apa dia \"Haawiyah\" itu?"],[101,11,6168,600,"نَارٌ حَامِيَةٌۢ","(Haawiyah itu ialah): api yang panas membakar."],[102,1,6169,600,"أَلْهَىٰكُمُ ٱلتَّكَاثُرُ","Kamu telah dilalaikan (daripada mengerjakan amal bakti) oleh perbuatan berlumba-lumba untuk mendapat dengan sebanyak-banyaknya (harta benda, anak-pinak pangkat dan pengaruh), -"],[102,2,6170,600,"حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ","Sehingga kamu masuk kubur."],[102,3,6171,600,"كَلَّا سَوْفَ تَعْلَمُونَ","Jangan sekali-kali (bersikap demikian)! Kamu akan mengetahui kelak (akibatnya yang buruk semasa hendak mati)!"],[102,4,6172,600,"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","Sekali lagi (diingatkan): jangan sekali-kali (kamu bersikap demikian)! Kamu akan mengetahui kelak akibatnya yang buruk pada hari kiamat)!"],[102,5,6173,600,"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ","Demi sesungguhnya! Kalaulah kamu mengetahui - (apa yang kamu akan hadapi) - dengan pengetahuan yang yakin, (tentulah kamu akan mengerjakan perkara-perkara yang menjadi bekalan kamu untuk hari akhirat)."],[102,6,6174,600,"لَتَرَوُنَّ ٱلْجَحِيمَ","(Ingatlah) demi sesungguhnya! - Kamu akan melihat neraka yang marak menjulang."],[102,7,6175,600,"ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ","Selepas itu - demi sesungguhnya! - kamu (wahai orang-orang yang derhaka) akan melihatnya dengan penglihatan yang yakin (semasa kamu dilemparkan ke dalamnya)!"],[102,8,6176,600,"ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ","Selain dari itu, sesungguhnya kamu akan ditanya pada hari itu, tentang segala nikmat (yang kamu telah menikmatinya)!"],[103,1,6177,601,"وَٱلْعَصْرِ","Demi Masa!"],[103,2,6178,601,"إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ","Sesungguhnya manusia itu dalam kerugian -"],[103,3,6179,601,"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ","Kecuali orang-orang yang beriman dan beramal soleh, dan mereka pula berpesan-pesan dengan kebenaran serta berpesan-pesan dengan sabar."],[104,1,6180,601,"وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ","Kecelakaan besar bagi tiap-tiap pencaci, pengeji,"],[104,2,6181,601,"ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ","Yang mengumpulkan harta dan berulang-ulang menghitung kekayaannya;"],[104,3,6182,601,"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","Ia menyangka bahawa hartanya itu dapat mengekalkannya (dalam dunia ini)!"],[104,4,6183,601,"كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ","Tidak! Sesungguhnya dia akan dicampakkan ke dalam \"Al-Hutamah\"."],[104,5,6184,601,"وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ","Dan apa jalannya engkau dapat mengetahui, apa dia \"Al-Hutamah\" itu?"],[104,6,6185,601,"نَارُ ٱللَّهِ ٱلْمُوقَدَةُ","(Al-Hutamah) ialah api Allah yang dinyalakan (dengan perintahNya), -"],[104,7,6186,601,"ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ","Yang naik menjulang ke hati;"],[104,8,6187,601,"إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ","Sesungguhnnya api neraka itu ditutup rapat atas mereka."],[104,9,6188,601,"فِى عَمَدٍۢ مُّمَدَّدَةٍۭ","(Mereka terikat di situ) pada batang-batang palang yang melintang panjang."],[105,1,6189,601,"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ","Tidakkah engkau mengetahui bagaimana Tuhanmu telah melakukan kepada angkatan tentera (yang dipimpin oleh pembawa) Gajah, (yang hendak meruntuhkan Kaabah)?"],[105,2,6190,601,"أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ","Bukankah Tuhanmu telah menjadikan rancangan jahat mereka dalam keadaan yang rugi dan memusnahkan mereka?"],[105,3,6191,601,"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","Dan Ia telah menghantarkan kepada mereka (rombongan) burung berpasuk-pasukan, -"],[105,4,6192,601,"تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ","Yang melontar mereka dengan batu-batu dari sejenis tanah yang dibakar keras, -"],[105,5,6193,601,"فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ","Lalu Ia menjadikan mereka hancur berkecai seperti daun-daun kayu yang dimakan ulat."],[106,1,6194,602,"لِإِيلَٰفِ قُرَيْشٍ","Kerana kebiasaan aman tenteram kaum Quraisy (penduduk Makkah)"],[106,2,6195,602,"إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ","(laitu) kebiasaan aman tenteram perjalanan mereka (menjalankan perniagaan) pada musim sejuk (ke negeri Yaman), dan pada musim panas (ke negeri Syam),"],[106,3,6196,602,"فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ","Maka hendaklah mereka menyembah Tuhan yang menguasai rumah (Kaabah) ini,"],[106,4,6197,602,"ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ","Tuhan yang memberi mereka penghidupan: menyelamatkan mereka dari kelaparan, dan mengamankan mereka dari ketakutan."],[107,1,6198,602,"أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ","Tahukah engkau akan orang yang mendustakan ugama (meliputi hari pembalasan)?"],[107,2,6199,602,"فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ","Orang itu ialah yang menindas serta berlaku zalim kepada anak yatim,"],[107,3,6200,602,"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","Dan ia tidak menggalakkan untuk memberi makanan yang berhak diterima oleh orang miskin."],[107,4,6201,602,"فَوَيْلٌۭ لِّلْمُصَلِّينَ","(Kalau orang yang demikian dikira dari bilangan orang-orang yang mendustakan ugama), maka kecelakaan besar bagi orang-orang Ahli Sembahyang -"],[107,5,6202,602,"ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ","(laitu) mereka yang berkeadaan lalai daripada menyempurnakan sembahyangnya;"],[107,6,6203,602,"ٱلَّذِينَ هُمْ يُرَآءُونَ","(Juga bagi) orang-orang yang berkeadaan riak (bangga diri dalam ibadat dan bawaannya),"],[107,7,6204,602,"وَيَمْنَعُونَ ٱلْمَاعُونَ","Dan orang-orang yang tidak memberi sedikit pertolongan (kepada orang yang berhak mendapatnya)."],[108,1,6205,602,"إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ","Sesungguhnya Kami telah mengurniakan kepadamu (wahai Muhammad) kebaikan yang banyak (di dunia dan di akhirat)."],[108,2,6206,602,"فَصَلِّ لِرَبِّكَ وَٱنْحَرْ","Oleh itu, kerjakanlah sembahyang kerana Tuhanmu semata-mata, dan sembelihlah korban (sebagai bersyukur)."],[108,3,6207,602,"إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ","Sesungguhnya orang yang bencikan engkau, Dia lah yang terputus (dari mendapat sebarang perkara yang diingininya)."],[109,1,6208,603,"قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ","Katakanlah (wahai Muhammad): \"Hai orang-orang kafir!"],[109,2,6209,603,"لَآ أَعْبُدُ مَا تَعْبُدُونَ","\"Aku tidak akan menyembah apa yang kamu sembah."],[109,3,6210,603,"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ","\"Dan kamu tidak mahu menyembah (Allah) yang aku sembah."],[109,4,6211,603,"وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ","\"Dan aku tidak akan beribadat secara kamu beribadat."],[109,5,6212,603,"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ","\"Dan kamu pula tidak mahu beribadat secara aku beribadat."],[109,6,6213,603,"لَكُمْ دِينُكُمْ وَلِىَ دِينِ","\"Bagi kamu ugama kamu, dan bagiku ugamaku\"."],[110,1,6214,603,"إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ","Apabila datang pertolongan Allah dan kemenangan (semasa engkau wahai Muhammad berjaya menguasai negeri Makkah), -"],[110,2,6215,603,"وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا","Dan engkau melihat manusia masuk dalam ugama Allah beramai-ramai, -"],[110,3,6216,603,"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا","Maka ucapkanlah tasbih dengan memuji Tuhanmu dan mintalah ampun kepadaNya, sesungguhnya Dia amat menerima taubat."],[111,1,6217,603,"تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ","Binasalah kedua-dua tangan Abu lahab, dan binasalah ia bersama!"],[111,2,6218,603,"مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ","Hartanya dan segala yang diusahakannya, tidak dapat menolongnya."],[111,3,6219,603,"سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ","Ia akan menderita bakaran api neraka yang marak menjulang."],[111,4,6220,603,"وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ","Dan juga isterinya, seorang perempuan pemunggah kayu api. -"],[111,5,6221,603,"فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ","Di lehernya sejenis tali, dari tali-tali yang dipintal."],[112,1,6222,604,"قُلْ هُوَ ٱللَّهُ أَحَدٌ","Katakanlah (wahai Muhammad): \"(Tuhanku) ialah Allah Yang Maha Esa;"],[112,2,6223,604,"ٱللَّهُ ٱلصَّمَدُ","\"Allah Yang menjadi tumpuan sekalian makhluk untuk memohon sebarang hajat;"],[112,3,6224,604,"لَمْ يَلِدْ وَلَمْ يُولَدْ","\"Ia tiada beranak, dan Ia pula tidak diperanakkan;"],[112,4,6225,604,"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","\"Dan tidak ada sesiapapun yang serupa denganNya\"."],[113,1,6226,604,"قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ","Katakanlah (wahai Muhammad); \"Aku berlindung kepada (Allah) Tuhan yang menciptakan sekalian makhluk,"],[113,2,6227,604,"مِن شَرِّ مَا خَلَقَ","\"Dari bencana makhluk-makhluk yang Ia ciptakan;"],[113,3,6228,604,"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","\"Dan dari bahaya gelap apabila ia masuk;"],[113,4,6229,604,"وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ","\"Dan dari kejahatan makhluk-makhluk yang menghembus-hembus pada simpulan-simpulan (dan ikatan-ikatan);"],[113,5,6230,604,"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","\"Dan dari kejahatan orang yang dengki apabila ia melakukan dengkinya\"."],[114,1,6231,604,"قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ","Katakanlah (wahai Muhammad): \"Aku berlindung kepada (Allah) Pemulihara sekalian manusia."],[114,2,6232,604,"مَلِكِ ٱلنَّاسِ","\"Yang Menguasai sekalian manusia,"],[114,3,6233,604,"إِلَٰهِ ٱلنَّاسِ","\"Tuhan yang berhak disembah oleh sekalian manusia,"],[114,4,6234,604,"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ","\"Dari kejahatan pembisik penghasut yang timbul tenggelam, -"],[114,5,6235,604,"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ","\"Yang melemparkan bisikan dan hasutannya ke dalam hati manusia, -"],[114,6,6236,604,"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","\"(Iaitu pembisik dan penghasut) dari kalangan jin dan manusia\"."]]);